def collect_warnings(monkeypatch):
    """[text] of every warning the launcher says from now on (warner: about a host path you chose)."""
    said = []
    monkeypatch.setattr(s, "warner", lambda warn=None: warn or said.append)
    return said


def test_warner(scenario, capsys, monkeypatch):
    """The launcher's way of saying a warning about a host path you chose: a WARN given is used as it is; else one
    line "agent-sandbox: warning: TEXT" on standard error, each text once per process, printable."""
    monkeypatch.setattr(s, "_WARNED", set())
    if scenario == "happy":
        said = []
        assert s.warner(said.append) == said.append
        s.warner()("Workspace / is the root directory")
        assert capsys.readouterr().err == "agent-sandbox: warning: Workspace / is the root directory\n"
    elif scenario == "sad":  # said once: a start checks some paths more than once
        s.warner()("the same")
        s.warner()("the same")
        assert capsys.readouterr().err.count("the same") == 1
    else:  # a path with control characters is shown escaped
        s.warner()("--mount /tmp/\x1b[2Jx is odd")
        assert "\x1b" not in capsys.readouterr().err


def test_safe_dest(scenario):
    if scenario == "sad":
        for dest in ("/work/../etc", "/work//file", "/work/./file", "/etc", "relative"):
            with pytest.raises(ValueError):
                s.safe_dest(dest)
    else:
        value = "/mnt" if scenario == "edge" else "/work/nested/file"
        assert s.safe_dest(value) == value


def test_parse_mount(scenario, tmp_path):
    if scenario == "sad":
        for mount in ("missing-separators", f"{tmp_path}/missing:/mnt/data:rw", f"{tmp_path}:/mnt/data:bad"):
            with pytest.raises(ValueError):
                s.parse_mount(mount)
        # A device: a mount of it cannot be used (the engines mount with nodev) - --device gives it.
        if Path("/dev/null").is_char_device():
            with pytest.raises(ValueError, match="is a device: a mount of it cannot be used.*--device"):
                s.parse_mount("/dev/null:/mnt/null:ro")
    elif scenario == "edge":
        # You decide: a socket (/var/run/docker.sock), also through a symlink, is mounted (check_given_path says what
        # runs behind it); the kernel's trees too.
        with socket.socket(socket.AF_UNIX) as server:
            server.bind(str(tmp_path / "engine.sock"))
            (tmp_path / "link").symlink_to(tmp_path / "engine.sock")
            for source in ("engine.sock", "link"):
                for mode in ("ro", "rw"):
                    assert s.parse_mount(f"{tmp_path / source}:/mnt/docker.sock:{mode}") == (
                        str(tmp_path / "engine.sock"), "/mnt/docker.sock", mode)
        assert s.parse_mount("/proc:/mnt/proc:ro") == ("/proc", "/mnt/proc", "ro")
        path = tmp_path / "colon: and spaces"
        path.write_text("unchanged")
        assert s.parse_mount(f"{path}:/mnt/reference:ro") == (str(path), "/mnt/reference", "ro")
    else:
        path = tmp_path / "reference"
        path.write_text("unchanged")
        assert s.parse_mount(f"{path}:/mnt/reference:ro") == (str(path), "/mnt/reference", "ro")
        assert path.read_text() == "unchanged"


def test_validate(scenario, tmp_path, monkeypatch):
    if scenario == "sad":
        cases = [["--network", "research", "--ip", "2001:db8::1"],
                 ["--network", "research", "--ip6", "192.0.2.1"],
                 ["--runtime", "/usr/bin"], ["--env", "INVALID=VALUE"],
                 ["--env", "UNSET_CONTRACT_VARIABLE"], ["--allow-host", "a..example.org"],
                 ["--offline", "--dns"], ["--offline", "--egress-all-allow"], ["--offline", "--nameserver", "1.1.1.1"],
                 ["--nameserver", "dns.example"], ["--nameserver", "1.1.1.1; accept"], ["--nameserver", "10.0.0.0/8"],
                 ["--allow-host-port", "3000", "--offline"], ["--allow-host-port", "3000", "--backend", "bwrap"],
                 ["--allow-host-port", "3000", "--network", "research"], ["--allow-host-port", "3000,0"],
                 ["--git-token-env", "https://github.com=UNSET_CONTRACT_VARIABLE"],
                 ["--git-token-env", "https://github.com=PATH", "--offline"],
                 ["--git-credentials", "/nonexistent/git-credentials"],
                 ["--git-token-env", "http://localhost:3080=UNSET_CONTRACT_VARIABLE"],
                 ["--git-token-env", "http://localhost:3080=PATH", "--backend", "bwrap"],
                 ["--git-token-env", "https://git.example.org=PATH", "--offline"],
                 ["--device", "/dev/console"], ["--device", "/dev/null"],
                 ["--gpu", "dri", "--podman-url", "unix:///example/podman.sock"]]
        monkeypatch.delenv("UNSET_CONTRACT_VARIABLE", raising=False)
        for args in cases:
            with pytest.raises(ValueError):
                s.validate(s.parse_args(["codex", *args]))
    else:
        workspace = tmp_path / ("new project" if scenario == "edge" else "work")
        args = s.parse_args(["codex", "--workspace", str(workspace), "--allow", "2001:db8::/32"])
        s.validate(args)
        assert args.workspace == str(workspace)
        assert not workspace.exists()


def test_prepare_workspace(scenario, tmp_path, capsys):
    path = tmp_path / "parent/work"
    if scenario == "sad":
        path.parent.mkdir()
        path.write_text("preserve")
        with pytest.raises(ValueError):
            s.prepare_workspace(path)
        assert path.read_text() == "preserve"
        # A file in its path: the reason in words, never a bare errno.
        with pytest.raises(ValueError, match="cannot be created: .* is a file, not a folder") as caught:
            s.prepare_workspace(path / "below")
        assert "Errno" not in str(caught.value)
    else:
        s.prepare_workspace(path)
        # A missing workspace is made, with its parents, and the start says so.
        assert f"created the workspace {path} (it was not there)" in capsys.readouterr().err
        mode = stat.S_IMODE(path.stat().st_mode)
        (path / "marker").write_text("preserve")
        if scenario == "edge":
            s.prepare_workspace(path)
        assert (path / "marker").read_text() == "preserve"
        assert stat.S_IMODE(path.stat().st_mode) == mode


def test_check_new_workspace(scenario, tmp_path, monkeypatch):
    """A folder named as a workspace that may not be there yet, checked as a start checks it: resolved, or refused with
    the reason (the app's Create now, Start and Apply ask this before making it)."""
    monkeypatch.setenv("XDG_RUNTIME_DIR", str(tmp_path / "runtime"))
    (tmp_path / "runtime").mkdir()
    if scenario == "happy":
        assert s.check_new_workspace(str(tmp_path / "new" / "project")) == tmp_path / "new" / "project"
        assert not (tmp_path / "new").exists(), "only checked: nothing made"
        assert s.check_new_workspace(tmp_path / "runtime" / ".." / "there") == tmp_path / "there"
    elif scenario == "sad":
        # You decide: a risk is said (WARN), never refused.
        for risky, why in ((tmp_path / "runtime" / "x", "XDG_RUNTIME_DIR"), (Path("/proc"), "kernel"),
                           (Path.home(), "HOME"), (Path(s.__file__).resolve().parent / "new", "sandbox-ai's own")):
            said = []
            assert s.check_new_workspace(risky, warn=said.append) == risky.resolve(strict=False)
            assert any(why in text for text in said), (risky, said)
        (tmp_path / "file").write_text("x")
        with pytest.raises(ValueError, match="is a file, not a folder"):
            s.check_new_workspace(tmp_path / "file" / "w")
    else:  # a link in its path to a place that is gone: refused, nothing made through it
        (tmp_path / "link").symlink_to(tmp_path / "gone")
        with pytest.raises(ValueError, match="dangling symlink"):
            s.check_new_workspace(tmp_path / "link" / "w")
        assert not (tmp_path / "gone").exists()


def test_create_workspace(scenario, tmp_path, monkeypatch, capsys):
    monkeypatch.setenv("XDG_RUNTIME_DIR", str(tmp_path / "runtime"))
    if scenario == "happy":
        made = s.create_workspace(str(tmp_path / "c0de" / "tor-network-another"))
        assert made == tmp_path / "c0de" / "tor-network-another" and made.is_dir()
        assert s.create_workspace(made) == made, "there already: used as it is"
    elif scenario == "sad":  # you decide: made, and what it means is said
        (tmp_path / "runtime").mkdir()
        said = []
        assert s.create_workspace(tmp_path / "runtime" / "w", warn=said.append).is_dir()
        assert any("XDG_RUNTIME_DIR" in text and "socket" in text for text in said), said
        (tmp_path / "file").write_text("x")
        with pytest.raises(ValueError, match="is a file, not a folder"):
            s.create_workspace(tmp_path / "file" / "w")
    else:
        monkeypatch.setattr(s.os, "access", lambda path, mode: False)  # (root writes anything)
        with pytest.raises(ValueError, match="is not writable for you"):
            s.create_workspace(tmp_path / "x" / "y")
        assert not (tmp_path / "x").exists()


def test_start_image_problems(scenario, tmp_path, monkeypatch):
    """The images a start needs, asked of Podman before anything is made (`podman image exists`): each one missing
    is a problem with its build (a Qwen start started its MCP servers first, then failed at "image not known")."""
    monkeypatch.delenv("SANDBOX_AI_MCP_NO_IMAGE_CHECK", raising=False)
    asked = []

    def exists(present):
        def run(command, **kwargs):
            asked.append(command)
            return subprocess.CompletedProcess(command, 0 if command[-1] in present else 1)
        return run
    monkeypatch.setattr(s.shutil, "which", lambda name: "/usr/bin/" + name)
    if scenario == "happy":
        monkeypatch.setattr(s.subprocess, "run", exists({"localhost/qwen-sandbox:latest"}))
        a = s.parse_args(["qwen", "--workspace", str(tmp_path)])
        assert s.start_image_problems(a) == [] and asked[0][:4] == ["podman", "image", "exists",
                                                                     "localhost/qwen-sandbox:latest"]
    elif scenario == "sad":
        monkeypatch.setattr(s.subprocess, "run", exists(set()))
        a = s.parse_args(["qwen", "--workspace", str(tmp_path), "--helper", "codex"])
        problems = s.start_image_problems(a)
        assert problems == [
            "The image of qwen (localhost/qwen-sandbox:latest) is not built on this host (nothing is pulled at a "
            "start): sandbox-ai build qwen",
            "The image of codex (localhost/codex-sandbox:latest) is not built on this host (nothing is pulled at a "
            "start): sandbox-ai build codex"]
        a = s.parse_args(["claude", "--workspace", str(tmp_path), "--image-variant", "web"])
        assert s.start_image_problems(a)[0].endswith("is not built on this host (nothing is pulled at a start): "
                                                      "sandbox-ai build --variant web")
        a = s.parse_args(["claude", "--workspace", str(tmp_path), "--cairn"])  # Cairn's own and the browser's
        assert [p.rsplit(": ", 1)[1] for p in s.start_image_problems(a)][-2:] == ["sandbox-ai build cairn",
                                                                                  "sandbox-ai build browser"]
        a = s.parse_args(["claude", "--workspace", str(tmp_path), "--image", "example.org/mine:1"])
        assert s.start_image_problems(a)[0].endswith(": podman pull example.org/mine:1, or build it")
        # Podman failing to answer (exit status 125) is not "not built": its own message is said.
        monkeypatch.setattr(s.subprocess, "run", lambda command, **kwargs: subprocess.CompletedProcess(
            command, 125, "", 'WARN[0000] noise\nError: database is locked'))
        problems = s.start_image_problems(s.parse_args(["qwen", "--workspace", str(tmp_path)]))
        assert problems == ["Podman could not say whether the image of qwen (localhost/qwen-sandbox:latest) is there "
                            "(podman image exists: exit status 125: Error: database is locked); check the host "
                            "with: sandbox-ai doctor"]
        monkeypatch.setattr(s.subprocess, "run", exists(set()))
        a = s.parse_args(["qwen", "--workspace", str(tmp_path), "--podman-url", "unix:///run/other.sock"])
        assert "not built on this host (Podman at unix:///run/other.sock)" in s.start_image_problems(a)[0]
        # Where it looked: Podman's image store and the user, so a build into another store shows.
        monkeypatch.setattr(s.subprocess, "run", lambda command, **kwargs: subprocess.CompletedProcess(
            command, 0 if command[1] == "info" else 1, "/home/me/.local/share/containers/storage\n", ""))
        assert "not built on this host (Podman's image store: /home/me/.local/share/containers/storage, user " in \
            s.start_image_problems(s.parse_args(["qwen", "--workspace", str(tmp_path)]))[0]
    else:
        # Not asked: the tests' switch, Bubblewrap (no image), no Podman here (the start says it later).
        monkeypatch.setattr(s.subprocess, "run", exists(set()))
        monkeypatch.setenv("SANDBOX_AI_MCP_NO_IMAGE_CHECK", "1")
        assert s.start_image_problems(s.parse_args(["qwen", "--workspace", str(tmp_path)])) == []
        monkeypatch.delenv("SANDBOX_AI_MCP_NO_IMAGE_CHECK")
        assert s.start_image_problems(s.parse_args(["claude", "--backend", "bwrap", "--workspace", str(tmp_path)])) \
            == []
        monkeypatch.setattr(s.shutil, "which", lambda name: None)
        assert s.start_image_problems(s.parse_args(["qwen", "--workspace", str(tmp_path)])) == [] and asked == []


def test_image_fix(scenario, tmp_path):
    a = s.parse_args(["qwen", "--workspace", str(tmp_path)])
    if scenario == "happy":
        assert s.image_fix(a, "qwen", a.image) == "sandbox-ai build qwen"
        assert s.image_fix(a, "the browser", s.BROWSER_IMAGE) == "sandbox-ai build browser"
        # The launcher's names of sandbox-ai's own images are those of their modules.
        assert s.BROWSER_IMAGE == s.load_browser_module().IMAGE
        assert s.CAIRN_IMAGE == load_module("sandbox_cairn_contracts", "sandbox/cairn.py").IMAGE
    elif scenario == "sad":
        assert s.image_fix(a, "qwen", "example.org/x:1") == "podman pull example.org/x:1, or build it"
    else:
        a = s.parse_args(["claude", "--workspace", str(tmp_path), "--image-variant", "web"])
        assert s.image_fix(a, "claude", a.image) == "sandbox-ai build --variant web"
        assert s.image_fix(a, "claude", s.TEAM_IMAGE) == "sandbox-ai build team"
        assert s.image_fix(a, "claude", s.CAIRN_IMAGE) == "sandbox-ai build cairn"


def test_check_workspace_creatable(scenario, tmp_path, monkeypatch):
    if scenario == "happy":
        s.check_workspace_creatable(tmp_path)  # there already
        s.check_workspace_creatable(tmp_path / "new" / "deeper")  # made at the start
    elif scenario == "sad":
        monkeypatch.setattr(s.os, "access", lambda path, mode: Path(path) != tmp_path)  # (root writes anything)
        with pytest.raises(ValueError, match=f"{tmp_path} is not writable for you"):
            s.check_workspace_creatable(tmp_path / "a" / "b")
        assert not (tmp_path / "a").exists()
    else:
        (tmp_path / "file").write_text("x")  # the nearest existing part is no folder: nothing can be made below
        with pytest.raises(ValueError, match=f"cannot be created: {tmp_path / 'file'} is a file, not a folder"):
            s.check_workspace_creatable(tmp_path / "file" / "w")


def test_check_mcp_names(scenario, tmp_path, monkeypatch):
    monkeypatch.setenv("XDG_CONFIG_HOME", str(tmp_path / "config"))
    a = s.parse_args(["codex", "--workspace", str(tmp_path), "--mcp", "demo"])
    if scenario == "happy":
        s.check_mcp_names(a)  # built-in
        a.mcp, a.helper_definitions = ["demo", "helper-codex-0123abcd"], {"helper-codex-0123abcd": {}}
        s.check_mcp_names(a)  # a --helper's server is defined by the start itself
    elif scenario == "sad":
        a.mcp = ["demo", "gone"]
        with pytest.raises(ValueError, match="Unknown MCP server: gone; defined: demo"):
            s.check_mcp_names(a)
        # Every problem of its MCP servers at once, before anything is made: the unknown one and the variable of a
        # command server (its variables are its options).
        a.mcp_env = ["demo:FLAG=1"]
        with pytest.raises(ValueError, match=r"^2 problems with the MCP servers of this start") as caught:
            s.check_mcp_names(a)
        assert "Unknown MCP server: gone" in str(caught.value) and "defined with a command" in str(caught.value)
    else:
        a.mcp, a.probe = ["gone"], True
        s.check_mcp_names(a)  # a probe starts no server: nothing to look up
        a.mcp_env = ["demo:FLAG=1"]
        with pytest.raises(ValueError, match="--mcp-env is for an agent's start with --mcp, not for a probe"):
            s.check_mcp_names(a)
        a.mcp_env = []
        a.probe, a.project_document = False, {"mcp_servers": {"gone": {"command": ["x"]}}}
        s.check_mcp_names(a)  # the trusted project file defines it


def test_unknown_mcp_message(scenario, tmp_path):
    a = s.parse_args(["codex", "--workspace", str(tmp_path), "--no-config"])
    if scenario == "happy":
        text = s.unknown_mcp_message(a, ["x"], {"demo": {}})
        assert text.startswith("Unknown MCP server: x; defined: demo") and "sandbox-ai mcp add" in text
    elif scenario == "sad":
        (tmp_path / ".sandbox-ai.json").write_text("{not json")  # only for the hint: never an error of its own
        assert "defines" not in s.unknown_mcp_message(a, ["x"], {})
    else:
        (tmp_path / ".sandbox-ai.json").write_text(json.dumps({"mcp_servers": {"x": {}}}))
        text = s.unknown_mcp_message(a, ["x", "y"], {})
        assert "defined: none" in text and "defines x, but this start reads no project file there" in text
        assert "--no-config" in text


def test_resolve_hosts(scenario, monkeypatch):
    if scenario == "sad":
        monkeypatch.setattr(s.socket, "getaddrinfo", lambda *a, **kw: [])
        with pytest.raises(ValueError, match="No addresses"):
            s.resolve_hosts(["example.org"])
    else:
        values = ["203.0.113.1"] if scenario == "happy" else ["2001:db8::1", "203.0.113.1", "203.0.113.1"]
        monkeypatch.setattr(s.socket, "getaddrinfo", lambda *a, **kw: [(0, 0, 0, "", (v, 443)) for v in values])
        assert s.resolve_hosts(["example.org"]) == {"example.org": sorted(set(values))}


def test_hosts_file(scenario):
    # Negative case: an empty permission list must not imply general DNS.
    values = {} if scenario == "sad" else {"example.org": ["203.0.113.1"]}
    if scenario == "edge":
        values["example.org"].append("2001:db8::1")
    text = s.hosts_file(values)
    assert text.startswith("127.0.0.1 localhost\n::1 localhost\n")
    assert "nameserver" not in text
    assert text.count(" example.org\n") == len(values.get("example.org", []))


def test_podman_command(scenario):
    options = ["--podman-url", "unix:///example/podman.sock"] if scenario == "edge" else []
    arg = "$(touch MUST_NOT_RUN)" if scenario == "sad" else "ps"
    cmd = s.podman_command(s.parse_args(["codex", *options]), "pod", arg)
    assert cmd[-2:] == ["pod", arg]
    assert ("--remote" in cmd) == (scenario == "edge")
    assert cmd[0] == "podman"


def test_resolve_pod_hosts(scenario, monkeypatch):
    run = Mock(return_value=Mock(stdout='{"example.org":["203.0.113.1","203.0.113.1"]}'))
    monkeypatch.setattr(s.subprocess, "run", run)
    args = s.parse_args(["codex"])
    if scenario == "sad":
        run.side_effect = subprocess.TimeoutExpired("podman", 45)
        with pytest.raises(ValueError, match="within 45 s"):
            s.resolve_pod_hosts(args, ["example.org"])
        # Podman itself failed (125): its own message and what helps, never only the command line.
        run.side_effect = subprocess.CalledProcessError(
            125, ["podman", "run"], output="", stderr="Error: localhost/codex-sandbox:latest: image not known\n")
        with pytest.raises(ValueError) as failed:
            s.resolve_pod_hosts(args, ["example.org"])
        text = str(failed.value)
        assert "exit status 125" in text and "image not known" in text and "sandbox-ai build codex" in text
    elif scenario == "edge":
        assert s.resolve_pod_hosts(args, []) == {}
        run.assert_not_called()
    else:
        assert s.resolve_pod_hosts(args, ["example.org"]) == {"example.org": ["203.0.113.1"]}
        assert run.call_args.kwargs["timeout"] == 45


def test_podman_failure(scenario):
    a = s.parse_args(["claude"])

    def failed(stderr):
        return s.podman_failure(a, subprocess.CalledProcessError(125, ["podman"], output="", stderr=stderr))
    if scenario == "happy":  # a known cause: what helps
        assert failed("Error: could not find pasta, the network namespace can't be configured: exec: \"pasta\"") \
            .endswith("-> the network needs pasta: install the package passt (Podman 4.4 or newer)")
        assert "subordinate IDs" in failed("cannot find UID/GID for user u: no subuid ranges found for user")
        # Without a user session four WARN lines come first, whatever the error: they decide nothing.
        warned = failed("WARN[0000] The cgroupv2 manager is set to systemd but there is no systemd user session\n"
                        "WARN[0000] Falling back to --cgroup-manager=cgroupfs\nError: something nobody has seen")
        assert "WARN" not in warned and "cgroups" not in warned and warned.endswith("sandbox-ai doctor")
        assert "pasta" not in failed("Error: invalid log driver: passthrough is only supported with a tty")
        assert "podman system migrate" in failed("Error: cannot re-exec process to join the existing user namespace")
        lookup = s.podman_failure(a, subprocess.CalledProcessError(1, ["podman"], output="",
                                                                   stderr="socket.gaierror: [Errno -2] Name unknown"))
        assert lookup.startswith("the host lookup in the image failed (exit status 1)")
        # 127 on the user's Proxmox container: pasta was missing ("executable file not found"), not python3.
        missing = s.podman_failure(a, subprocess.CalledProcessError(
            127, ["podman"], output="", stderr='Error: could not find pasta, the network namespace cannot be '
                                               'configured: exec: "pasta": executable file not found in $PATH'))
        assert missing.startswith("Podman could not start a program it needs (pasta, or the image's python3) "
                                  "(exit status 127)")
        assert missing.endswith("install the package passt (Podman 4.4 or newer)")
        # The same 127 when pasta is there but the container has no /dev/net/tun (the user's Proxmox container).
        tun = s.podman_failure(a, subprocess.CalledProcessError(
            127, ["podman"], output="", stderr="Error: pasta failed with exit code 1:\nFailed to open() /dev/net/tun: "
                                               "No such file or directory\nFailed to set up tap device in namespace"))
        assert "install the package passt" not in tun, "pasta is installed: no advice to install it"
        assert "lxc.mount.entry: /dev/net/tun dev/net/tun none bind,create=file" in tun and "modprobe tun" in tun
        assert "pasta could not set up the network" in failed("Error: pasta failed with exit code 1: something else")
        assert s.podman_failure(a, subprocess.CalledProcessError(127, ["podman"], output="", stderr="")) \
            .endswith("-> check the host with: sandbox-ai doctor")
        lxc = failed('newuidmap: write to uid_map failed: Operation not permitted\nError: cannot set up namespace '
                     'using "/usr/bin/newuidmap": exit status 1')
        assert "unprivileged container" in lxc and "sandbox-ai doctor" in lxc
        few = failed("Error: potentially insufficient UIDs or GIDs available in user namespace (requested 0:65534 "
                     "for /nonexistent): Check /etc/subuid and /etc/subgid")
        assert "higher IDs" in few and "65536" in few
        assert "sandbox-ai build claude" in failed("Error: localhost/claude-sandbox:latest: image not known")
    elif scenario == "sad":  # an unknown one: Podman's message, and the doctor
        text = failed("Error: something new")
        assert "something new" in text and text.endswith("-> check the host with: sandbox-ai doctor")
    else:  # no message at all, or one with control characters: still readable, never a terminal sequence
        assert s.podman_failure(a, subprocess.CalledProcessError(125, ["podman"], output="", stderr="")) \
            == "Podman failed (exit status 125) before the sandbox started\n  -> check the host with: sandbox-ai doctor"
        assert "\x1b" not in failed("\x1b]0;evil\x07 image not known")


def test_firewall_rules(scenario):
    if scenario == "sad":
        with pytest.raises(ValueError):
            s.firewall_rules(["203.0.113.1; accept"], [])
    else:
        rules = s.firewall_rules(["192.0.2.5/24"] if scenario == "happy" else [],
                                 ["2001:db8::1", "2001:db8::1"] if scenario == "happy" else [])
        assert rules.count("policy drop") == 3
        assert rules.count("ip6 daddr 2001:db8::1 tcp dport 443 accept") == (1 if scenario == "happy" else 0)
        assert "udp dport 53 accept" not in rules
    if scenario == "edge":
        # A VPN's own rules (vpn.py: Tor's ports) come first in the output chain, before loopback is accepted.
        rules = s.firewall_rules([], [], vpn_rules=["ip daddr 127.0.53.1 drop"])
        output = rules.split(" chain output")[1]
        assert output.index("ip daddr 127.0.53.1 drop") < output.index('oifname "lo" accept')
    if scenario == "sad":
        with pytest.raises(ValueError, match="firewall rule"):
            s.firewall_rules([], [], vpn_rules=["accept }\n chain x {"])


