def test_mcp_serve(scenario, tmp_path):
    import threading, time as clock
    sock = tmp_path / "s.sock"
    if scenario == "sad":
        with pytest.raises(OSError):
            s.mcp_serve(str(tmp_path / "missing-dir" / "s.sock"), ["cat"])
        return
    if scenario == "edge":
        sock.write_text("stale")  # A stale socket file is replaced.
    command = ["cat"] if scenario == "happy" else ["/nonexistent/server"]
    threading.Thread(target=s.mcp_serve, args=(str(sock), command), kwargs={"cwd": str(tmp_path)}, daemon=True).start()
    for _ in range(100):
        if sock.exists() and sock.is_socket():
            break
        clock.sleep(0.05)
    ping = b'{"jsonrpc": "2.0", "method": "ping", "id": 1}\n'

    def exchange(data=ping):
        client = socket.socket(socket.AF_UNIX)
        client.settimeout(10)
        client.connect(str(sock))
        client.sendall(data)
        client.shutdown(socket.SHUT_WR)
        received = b""
        try:
            while chunk := client.recv(100):
                received += chunk
        except ConnectionResetError:
            pass  # a failed server closes with unread input
        return received
    # cat sends the request back (no answer to it): once it ends, the relay answers the request still open - with
    # why it ended (tests/test_mcp_live_start.py).
    # (0.2.1: the reason ends with where the human sees more)
    unanswered = b'{"jsonrpc": "2.0", "id": 1, "error": {"code": -32000, "message": "sandbox-ai: the MCP server ended ' \
                 b'before it answered (exit status 0, nothing on its error output); the human sees more: sandbox-ai ' \
                 b'mcp list"}}\n'
    # A server that cannot be started answers the request with why, instead of closing without a word (0.2.1).
    not_started = b'{"jsonrpc": "2.0", "id": 1, "error": {"code": -32000, "message": "sandbox-ai: the MCP server could ' \
                  b'not be started (No such file or directory); the human sees more: sandbox-ai mcp list"}}\n'
    assert exchange() == (ping + unanswered if scenario == "happy" else not_started)
    # One failing or finished instance never takes the listener down.
    assert exchange() == (ping + unanswered if scenario == "happy" else not_started)
    if scenario == "happy":
        # What is not one JSON message never reaches the server: the relay answers it.
        answer = json.loads(exchange(b"echo\n"))
        assert answer["error"]["code"] == -32700 and answer["id"] is None


def test_mcp_show_hint(scenario):
    """Where the human sees more about a server that failed: its name (an instance's NAME.HASH: NAME), else the list."""
    if scenario == "happy":
        assert s.RUNTIME.mcp_show_hint("gowitness.ab12cd") == "the human sees more: sandbox-ai mcp show gowitness"
    elif scenario == "sad":
        assert s.RUNTIME.mcp_show_hint("x; rm -rf /") == "the human sees more: sandbox-ai mcp list"  # never echoed
    else:
        assert s.RUNTIME.mcp_show_hint(None) == s.RUNTIME.mcp_show_hint("a" * 33) == \
            "the human sees more: sandbox-ai mcp list"


def test_mcp_failure_record(scenario, tmp_path):
    """A server's failure lands in its safeguards records (mcp list/show, doctor read it), redacted and bounded."""
    path = tmp_path / "safeguards.jsonl"
    env = {"SANDBOX_AI_MCP_RECORDS": str(path), "SANDBOX_AI_MCP_INSTANCE": "gowitness.ab12"}
    if scenario == "happy":
        entry = s.RUNTIME.mcp_failure_record("ended before it answered", "exit status 126", "sandbox-ai mcp check x",
                                             environ=env)
        written = json.loads(path.read_text().splitlines()[-1])
        assert written == entry and entry["target"] == "gowitness" and entry["kind"] == "mcp-server"
        assert entry["why"] == "exit status 126" and entry["fix"] == "sandbox-ai mcp check x"
    elif scenario == "sad":
        assert s.RUNTIME.mcp_failure_record("x", "y", "z", environ={}) is None  # no records file: nothing written
        assert not path.exists()
        (tmp_path / "elsewhere").write_text("")
        path.symlink_to(tmp_path / "elsewhere")  # never followed
        s.RUNTIME.mcp_failure_record("x", "y", "z", environ=env)
        assert (tmp_path / "elsewhere").read_text() == ""
    else:
        entry = s.RUNTIME.mcp_failure_record("w" * 1000, "\x1b[31mred\n" * 100, "f", environ=env)
        # (cut to 300 characters, then escaped: never a control character, never unbounded)
        assert len(entry["what"]) <= 300 and len(entry["why"]) <= 3 * 300 and "\x1b" not in entry["why"]


def test_mcp_answer_refused(scenario):
    """A connection that gets no server is answered with the reason on its first request (an agent then tells its
    human why), and closed; bounded in what it reads."""
    ours, theirs = socket.socketpair()
    with theirs:
        if scenario == "happy":
            theirs.sendall(b'{"jsonrpc": "2.0", "method": "initialize", "id": 7}\n')
            s.RUNTIME.mcp_answer_refused(ours, "its image is not there", wait=5)
            answer = json.loads(theirs.makefile("rb").readline())
            assert answer == {"jsonrpc": "2.0", "id": 7, "error": {"code": -32000,
                                                                   "message": "sandbox-ai: its image is not there"}}
        elif scenario == "sad":
            # A notification (no id), then something that is not JSON: never answered, the connection just closes.
            theirs.sendall(b'{"jsonrpc": "2.0", "method": "notifications/initialized"}\nnot json\n')
            theirs.shutdown(socket.SHUT_WR)
            s.RUNTIME.mcp_answer_refused(ours, "why", wait=5)
            assert theirs.makefile("rb").read() == b""
        else:
            # Nothing comes within the wait: it gives up without an answer (and never blocks longer).
            started = time.monotonic()
            s.RUNTIME.mcp_answer_refused(ours, "why", wait=0.2)
            assert time.monotonic() - started < 3
            assert theirs.makefile("rb").read() == b""


def test_mcp_bridge(scenario, tmp_path, monkeypatch):
    if scenario == "sad":
        with pytest.raises(RuntimeError, match="unavailable"):
            s.mcp_bridge(str(tmp_path / "absent.sock"))
        return
    import threading
    server = socket.socket(socket.AF_UNIX)
    server.bind(str(tmp_path / "b.sock"))
    server.listen(1)
    payload = b"x" * (300000 if scenario == "edge" else 5)
    def answer():
        connection, _ = server.accept()
        with connection:
            while connection.recv(65536):
                pass
            connection.sendall(payload)
    threading.Thread(target=answer, daemon=True).start()
    read_r, read_w = os.pipe()
    write_r, write_w = os.pipe()
    os.write(read_w, b"request")
    os.close(read_w)
    saved = os.dup(0), os.dup(1)
    os.dup2(read_r, 0)
    os.dup2(write_w, 1)
    received = []
    reader = threading.Thread(target=lambda: received.append(b"".join(iter(lambda: os.read(write_r, 65536), b""))))
    reader.start()
    try:
        assert s.mcp_bridge(str(tmp_path / "b.sock")) == 0
    finally:
        os.dup2(saved[0], 0)
        os.dup2(saved[1], 1)
        os.close(write_w)
        reader.join(10)
    assert received == [payload]


def test_config_key(scenario, tmp_path):
    real = tmp_path / "real"
    real.mkdir()
    if scenario == "happy":
        assert s.config_key(real / ".sandbox-ai.json") == real / ".sandbox-ai.json"
    elif scenario == "sad":
        # The file name itself is never followed, even when it is a link.
        (real / "target.json").write_text("{}")
        (real / ".sandbox-ai.json").symlink_to(real / "target.json")
        assert s.config_key(real / ".sandbox-ai.json").name == ".sandbox-ai.json"
    else:
        (tmp_path / "alias").symlink_to(real)
        assert s.config_key(tmp_path / "alias" / ".sandbox-ai.json") == real / ".sandbox-ai.json"


def test_read_config_bytes(scenario, tmp_path):
    path = tmp_path / "c.json"
    if scenario == "happy":
        path.write_bytes(b'{"a": 1}')
        assert s.read_config_bytes(path) == b'{"a": 1}'
    elif scenario == "sad":
        (tmp_path / "t.json").write_text("{}")
        path.symlink_to(tmp_path / "t.json")
        with pytest.raises(ValueError, match="symlink"):
            s.read_config_bytes(path)
        os.mkfifo(tmp_path / "fifo")
        with pytest.raises(ValueError, match="regular file"):
            s.read_config_bytes(tmp_path / "fifo")
    else:
        path.write_bytes(b"x" * (s.CONFIG_LIMIT + 1))
        with pytest.raises(ValueError, match="larger"):
            s.read_config_bytes(path)


def test_attach_frame(scenario):
    import struct as st
    kind, payload = {"happy": (b"d", b"ls\r"), "sad": (b"r", st.pack("!HH", 40, 120)), "edge": (b"d", b"")}[scenario]
    frame = s.attach_frame(kind, payload)
    assert frame[:1] == kind and st.unpack("!I", frame[1:5])[0] == len(payload) and frame[5:] == payload


def test_read_frames(scenario):
    import struct as st
    data = s.attach_frame(b"d", b"abc") + s.attach_frame(b"r", st.pack("!HH", 30, 100))
    if scenario == "happy":
        frames, rest = s.read_frames(data)
        assert frames == [(b"d", b"abc"), (b"r", st.pack("!HH", 30, 100))] and rest == b""
    elif scenario == "sad":
        frames, rest = s.read_frames(data[:10])  # an incomplete second header stays buffered
        assert frames == [(b"d", b"abc")] and rest == data[8:10]
    else:
        frames, rest = s.read_frames(data[:3])
        assert frames == [] and rest == data[:3]


def relay_round_trip(tmp_path, child_script, frames):
    import threading, time as clock
    sock = tmp_path / "attach.sock"
    command = [sys.executable, "-c", child_script]
    threading.Thread(target=s.attach_relay, args=(str(sock), command), daemon=True).start()
    for _ in range(200):
        if sock.exists():
            break
        clock.sleep(0.02)
    client = socket.socket(socket.AF_UNIX)
    client.settimeout(15)
    client.connect(str(sock))
    for frame in frames:
        client.sendall(frame)
    received = b""
    try:
        while chunk := client.recv(4096):
            received += chunk
    except ConnectionResetError:
        pass
    return received


def test_attach_relay(scenario, tmp_path):
    import struct as st
    script = ("import os,sys; r,c=os.get_terminal_size(0).lines,os.get_terminal_size(0).columns; "
              "print('SIZE',r,c,flush=True); line=sys.stdin.readline(); print('GOT',line.strip(),flush=True)")
    if scenario == "sad":
        out = relay_round_trip(tmp_path, "import sys; sys.exit(3)", [])
        assert out == b""  # the attach client ended: connection closed, relay keeps serving
        return
    size = (30, 100) if scenario == "happy" else (12, 345)
    out = relay_round_trip(tmp_path, script, [s.attach_frame(b"r", st.pack("!HH", *size)),
                                              s.attach_frame(b"d", b"hello\r")])
    assert f"SIZE {size[0]} {size[1]}".encode() in out and b"GOT hello" in out


def test_attach_client(scenario, tmp_path):
    import threading
    sock = tmp_path / "c.sock"
    if scenario == "sad":
        with pytest.raises(RuntimeError, match="not reachable"):
            s.attach_client(str(sock), os.open(os.devnull, os.O_RDONLY), os.open(os.devnull, os.O_WRONLY))
        # The sandbox swaps attach.sock for a symlink to another host socket of the user:
        # the client refuses instead of sending keystrokes there.
        victim = socket.socket(socket.AF_UNIX)
        victim.bind(str(tmp_path / "victim.sock"))
        victim.listen(1)
        victim.settimeout(0.5)
        sock.symlink_to(tmp_path / "victim.sock")
        with pytest.raises(RuntimeError, match="not reachable"):
            s.attach_client(str(sock), os.open(os.devnull, os.O_RDONLY), os.open(os.devnull, os.O_WRONLY))
        with pytest.raises(OSError):
            victim.accept()
        sock.unlink()
        (tmp_path / "plain").write_text("")  # not a socket at all
        with pytest.raises(RuntimeError, match="not a socket"):
            s.attach_client(str(tmp_path / "plain"), os.open(os.devnull, os.O_RDONLY), os.open(os.devnull, os.O_WRONLY))
        return
    server = socket.socket(socket.AF_UNIX)
    server.bind(str(sock))
    server.listen(1)
    got = []
    # A hostile relay sends a tmux-style exec request: the client only ever writes bytes out.
    hostile = b"\x00\x00\x00\x0cMSG_EXEC rm -rf ~" if scenario == "edge" else b"screen output"
    def serve():
        connection, _ = server.accept()
        with connection:
            data = b""
            while b"typed" not in data:
                chunk = connection.recv(4096)
                if not chunk:
                    break
                data += chunk
            got.append(data)
            connection.sendall(hostile)
    threading.Thread(target=serve, daemon=True).start()
    stdin_r, stdin_w = os.pipe()
    os.write(stdin_w, b"typed")
    os.close(stdin_w)
    out_r, out_w = os.pipe()
    assert s.attach_client(str(sock), stdin_r, out_w) == 0
    os.close(out_w)
    assert os.read(out_r, 4096) == hostile
    frames, _ = s.read_frames(got[0])
    assert (b"d", b"typed") in frames


# --- sandbox-ai shell: the relay in the sandbox and its client (more in tests/test_shell.py) ----------------------

def shell_relay_at(tmp_path, name="shell.sock"):
    """A shell relay serving in this process (its working directory TMP_PATH/work); its socket's path."""
    work = tmp_path / "work"
    work.mkdir(exist_ok=True)
    path = tmp_path / name
    threading.Thread(target=s.RUNTIME.shell_relay, args=(str(path), str(work)), daemon=True).start()
    for _ in range(250):
        if path.exists():
            break
        time.sleep(0.02)
    return str(path)


def shell_run(path, argv, tty=False, given=b""):
    """(status, output, error output) of shell_client running ARGV through the relay at PATH, GIVEN as its input."""
    stdin_r, stdin_w = os.pipe()
    os.write(stdin_w, given)
    os.close(stdin_w)
    out_r, out_w = os.pipe()
    err_r, err_w = os.pipe()
    result = {}

    def drain(fd, key):
        data = b""
        while chunk := os.read(fd, 65536):
            data += chunk
        result[key] = data
        os.close(fd)
    readers = [threading.Thread(target=drain, args=(out_r, "out")), threading.Thread(target=drain, args=(err_r, "err"))]
    for reader in readers:
        reader.start()
    try:
        status = s.RUNTIME.shell_client(path, argv, tty, stdin_r, out_w, err_w)
    finally:
        for fd in (stdin_r, out_w, err_w):
            os.close(fd)
        for reader in readers:
            reader.join(10)
    return status, result.get("out", b""), result.get("err", b"")


def test_relay_shell(scenario, tmp_path):
    """A command with its input, output, error output and exit status; bash without one; the working directory."""
    path = shell_relay_at(tmp_path)
    if scenario == "happy":
        status, out, err = shell_run(path, ["sh", "-c", "cat; pwd; echo warned >&2; exit 7"], given=b"line 1\nline 2\n")
        assert status == 7 and out == f"line 1\nline 2\n{tmp_path / 'work'}\n".encode() and err == b"warned\n"
    elif scenario == "sad":
        status, out, err = shell_run(path, ["no-such-command-here"])
        assert status == 127 and out == b"" and b"sandbox-ai shell: no-such-command-here:" in err
        assert shell_run(path, ["sh", "-c", "kill -TERM $$"])[0] == 128 + signal.SIGTERM
    else:
        # Without a command: bash, reading its commands from the input; much output arrives whole.
        status, out, _ = shell_run(path, [], given=b"head -c 300000 /dev/zero | tr '\\0' x; exit 3\n")
        assert status == 3 and out == b"x" * 300000


def test_shell_relay(scenario, tmp_path, monkeypatch):
    """On a terminal: the size and type of the client's; what the relay refuses closes the connection unrun."""
    path = shell_relay_at(tmp_path)
    if scenario == "happy":
        monkeypatch.setenv("TERM", "xterm-256color")
        status, out, err = shell_run(path, ["sh", "-c", 'tty; stty size; echo "T=$TERM"; exit 4'], tty=True)
        lines = out.decode().split("\r\n")
        assert status == 4 and err == b"" and lines[0].startswith("/dev/pts/") and lines[1:3] == ["24 80",
                                                                                                "T=xterm-256color"]
        return
    client = socket.socket(socket.AF_UNIX)
    client.settimeout(10)
    client.connect(path)
    if scenario == "sad":  # input before any request, or a bad one
        client.sendall(s.attach_frame(b"d", b"rm -rf /\n"))
    else:  # a frame of gigabytes announced
        client.sendall(b"c" + struct.pack("!I", s.RUNTIME.SHELL_FRAME_LIMIT + 1) + b"{")
    assert client.recv(4096) == b""
    client.close()


def test_shell_client(scenario, tmp_path):
    """Only bytes and one exit status (0-255) from what answers on the socket (a folder the sandbox can write); no
    symlink there is followed to another socket of the user."""
    path = tmp_path / "shell.sock"
    if scenario == "sad":
        victim = socket.socket(socket.AF_UNIX)
        victim.bind(str(tmp_path / "control.sock"))
        victim.listen(1)
        victim.settimeout(0.5)
        path.symlink_to(tmp_path / "control.sock")
        with pytest.raises(RuntimeError, match="not reachable"):
            shell_run(str(path), ["ls"])
        with pytest.raises(OSError):
            victim.accept()
        return
    server = socket.socket(socket.AF_UNIX)
    server.bind(str(path))
    server.listen(1)
    got = []

    def serve():
        connection, _ = server.accept()
        with connection:
            got.append(connection.recv(65536))
            if scenario == "happy":
                connection.sendall(s.attach_frame(b"o", b"\x00\x00\x00\x0cMSG_EXEC rm -rf ~")
                                   + s.attach_frame(b"?", b"unknown") + s.attach_frame(b"x", struct.pack("!i", 9999)))
            else:  # it says a frame of gigabytes follows
                connection.sendall(b"o" + struct.pack("!I", 1 << 31))
    threading.Thread(target=serve, daemon=True).start()
    status, out, _ = shell_run(str(path), ["ls", "-l"])
    frames, _ = s.read_frames(got[0])
    assert frames[0][0] == b"c" and json.loads(frames[0][1])["argv"] == ["ls", "-l"]
    if scenario == "happy":
        assert out == b"\x00\x00\x00\x0cMSG_EXEC rm -rf ~" and status == 255  # 9999, bounded
    else:
        assert out == b"" and status == s.RUNTIME.SHELL_NO_STATUS


def test_serve_relay(scenario, tmp_path):
    path = tmp_path / {"happy": "a.sock", "sad": "b.sock", "edge": "c.sock"}[scenario]
    seen = []
    threading.Thread(target=s.RUNTIME.serve_relay, args=(str(path), lambda c, *a: seen.append(a) or c.close(),
                                                         scenario), daemon=True).start()
    for _ in range(250):
        if path.exists():
            break
        time.sleep(0.02)
    for _ in range(1 if scenario != "edge" else 3):  # each connection its own handler, the listener stays
        client = socket.socket(socket.AF_UNIX)
        client.connect(str(path))
        client.settimeout(5)
        assert client.recv(10) == b""
        client.close()
    assert seen == [(scenario,)] * (1 if scenario != "edge" else 3)


def test_frames_within(scenario):
    data = s.attach_frame(b"d", b"abc") + s.attach_frame(b"r", b"1234")
    if scenario == "happy":
        assert s.RUNTIME.frames_within(data) == ([(b"d", b"abc"), (b"r", b"1234")], b"")
    elif scenario == "sad":
        with pytest.raises(ValueError, match="larger"):
            s.RUNTIME.frames_within(data + b"o" + struct.pack("!I", 11), limit=10)
    else:  # a header not complete yet: kept for the next read
        assert s.RUNTIME.frames_within(data + b"o\x00") == ([(b"d", b"abc"), (b"r", b"1234")], b"o\x00")


def test_hung_up(scenario):
    import socket
    mine, theirs = socket.socketpair()
    try:
        if scenario == "happy":  # the other end closed it
            theirs.close()
            assert s.RUNTIME.hung_up(mine)
        elif scenario == "sad":  # open, nothing sent
            assert not s.RUNTIME.hung_up(mine)
        else:  # data waiting is no hangup (it is not read here)
            theirs.sendall(b"x")
            assert not s.RUNTIME.hung_up(mine)
    finally:
        mine.close()
        with contextlib.suppress(OSError):
            theirs.close()


def test_shell_request(scenario):
    if scenario == "happy":
        assert s.RUNTIME.shell_request(json.dumps({"argv": ["ls", "-l"], "tty": True, "term": "xterm"}).encode()) == \
            (["ls", "-l"], True, "xterm")
    elif scenario == "sad":
        for bad in ({"argv": "ls", "tty": False}, {"argv": ["a\0b"], "tty": False}, {"argv": [], "tty": "yes"}, []):
            with pytest.raises(ValueError):
                s.RUNTIME.shell_request(json.dumps(bad).encode())
        with pytest.raises(ValueError, match="too large"):
            s.RUNTIME.shell_request(b" " * (s.RUNTIME.SHELL_REQUEST_LIMIT + 1))
    else:  # no command: a shell; a TERM that is no plain name is not taken
        assert s.RUNTIME.shell_request(b'{"argv": null, "tty": false, "term": "x;$(y)"}') == ([], False, None)


def test_read_available(scenario):
    read_end, write_end = os.pipe()
    os.set_blocking(read_end, False)
    try:
        if scenario == "happy":
            os.write(write_end, b"data")
            assert s.RUNTIME.read_available(read_end) == b"data"
        elif scenario == "sad":
            os.close(write_end)
            write_end = None
            assert s.RUNTIME.read_available(read_end) is None  # its end
        else:
            assert s.RUNTIME.read_available(read_end) == b""  # nothing there now
            assert s.RUNTIME.read_available(-1) is None
    finally:
        os.close(read_end)
        if write_end is not None:
            os.close(write_end)


def test_end_process_group(scenario):
    script = {"happy": "echo; sleep 60", "sad": "trap '' HUP; echo; sleep 60 & wait", "edge": "exit 0"}[scenario]
    child = subprocess.Popen(["sh", "-c", script], start_new_session=True, stdout=subprocess.PIPE)
    if scenario == "edge":
        child.wait()
    else:
        child.stdout.readline()  # its trap is set
    child.stdout.close()
    s.RUNTIME.end_process_group(child, grace=0.3)
    assert child.returncode is not None
    if scenario == "sad":  # what ignores SIGHUP is killed after the grace
        assert child.returncode == -signal.SIGKILL


def test_write_all(scenario):
    read_end, write_end = os.pipe()
    data = {"happy": b"abc", "sad": b"", "edge": b"y" * 200000}[scenario]  # more than a pipe holds: written whole
    got = []

    def drain():
        while chunk := os.read(read_end, 65536):
            got.append(chunk)
    reader = threading.Thread(target=drain)
    reader.start()
    s.RUNTIME.write_all(write_end, data)
    os.close(write_end)
    reader.join(10)
    os.close(read_end)
    assert b"".join(got) == data


