def test_save_trusted(scenario, tmp_path, monkeypatch):
    monkeypatch.setenv("XDG_CONFIG_HOME", str(tmp_path / "cfg"))
    data = {"happy": {"/p/.sandbox-ai.json": "ab" * 32}, "sad": {}, "edge": {"/ü ñ/x": "cd" * 32}}[scenario]
    s.save_trusted(data)
