def test_start_memory_watch(scenario, monkeypatch, tmp_path):
    a = s.parse_args(["claude", *(["--memory", "none", "--cpus", "none", "--pids", "none"] if scenario == "sad"
                                  else [])])
    monkeypatch.setattr(s, "enforced_limits", lambda a: (s.resource_limits(a), []))
