def test_share_browser_ca(scenario, tmp_path):
    ca_dir, run = tmp_path / "ca", tmp_path / "run"
    ca_dir.mkdir()
    run.mkdir()
    certificate = b"-----BEGIN CERTIFICATE-----\nMIIB\n-----END CERTIFICATE-----\n"
    if scenario == "happy":
        (ca_dir / "ca.pem").write_bytes(certificate)
        assert s.RUNTIME.share_browser_ca(run, ca_dir) is True
        assert (run / s.RUNTIME.BROWSER_CA).read_bytes() == certificate
        assert stat.S_IMODE((run / s.RUNTIME.BROWSER_CA).stat().st_mode) == 0o644
    elif scenario == "sad":  # no proxy (no CA), or anything with a key in it: nothing shared
        assert s.RUNTIME.share_browser_ca(run, ca_dir) is False
        (ca_dir / "ca.pem").write_bytes(certificate + b"-----BEGIN " + b"PRIVATE KEY-----\n")
        assert s.RUNTIME.share_browser_ca(run, ca_dir) is False and not (run / s.RUNTIME.BROWSER_CA).exists()
    else:  # a directory that cannot be written: False, nothing left behind
        (ca_dir / "ca.pem").write_bytes(certificate)
        assert s.RUNTIME.share_browser_ca(tmp_path / "missing", ca_dir) is False


def test_port_open(scenario):
    if scenario == "happy":
        with socket.socket() as server:
            server.bind(("127.0.0.1", 0))
            server.listen()
            assert s.RUNTIME.port_open(server.getsockname()[1])
    elif scenario == "sad":
        with socket.socket() as probe:
            probe.bind(("127.0.0.1", 0))
            port = probe.getsockname()[1]  # bound, never listening
        assert not s.RUNTIME.port_open(port, timeout=0.2)
    else:  # IPv6 loopback only (where the host has it)
        try:
            server = socket.socket(socket.AF_INET6)
            server.bind(("::1", 0))
        except OSError:
            pytest.skip("no IPv6 loopback here")
        with server:
            server.listen()
            assert s.RUNTIME.port_open(server.getsockname()[1])


def test_await_services(scenario, tmp_path):
    rt_ = s.RUNTIME
    services = [{"name": "db", "ready": 5432, "timeout": 5}, {"name": "x", "ready": None}]
    if scenario == "happy":  # started by the launcher, ready after two looks
        (tmp_path / rt_.SERVICES_STARTED).write_text(json.dumps({"ok": True}))
        opened = iter([False, False, True])
        assert rt_.await_services(services, tmp_path, opened=lambda port: next(opened), sleep=lambda _: None) is None
        assert (tmp_path / rt_.SERVICES_GO).exists()
    elif scenario == "sad":  # one did not start, one never got ready, or nobody answered: the start stops
        (tmp_path / rt_.SERVICES_STARTED).write_text(json.dumps({"ok": False, "error": "the service db did not "
                                                                                         "start: x"}))
        assert rt_.await_services(services, tmp_path) == "the service db did not start: x"
        (tmp_path / rt_.SERVICES_STARTED).write_text(json.dumps({"ok": True}))
        clock = iter(range(0, 100_000, 10))
        assert "did not accept connections on port 5432" in rt_.await_services(
            services, tmp_path, opened=lambda port: False, clock=lambda: next(clock), sleep=lambda _: None)
        (tmp_path / rt_.SERVICES_STARTED).unlink()
        clock = iter(range(0, 100_000, 100))
        assert "not started within" in rt_.await_services(services, tmp_path, clock=lambda: next(clock),
                                                          sleep=lambda _: None)
        (tmp_path / rt_.SERVICES_STARTED).write_text("{")
        assert "cannot be read" in rt_.await_services(services, tmp_path)
        assert "cannot be started" in rt_.await_services(services, tmp_path / "missing")
    else:  # no services: nothing written, nothing waited for
        assert rt_.await_services([], tmp_path) is None and not (tmp_path / rt_.SERVICES_GO).exists()
        (tmp_path / rt_.SERVICES_STARTED).write_text(json.dumps({"ok": True}))
        assert rt_.await_services([{"name": "x", "ready": True}], tmp_path) is None  # no port: not waited for


# --- the --llm server's requests: parameters and the loop guard (runtime.llm_*; more in tests/test_llm_loops.py) ---

LOOP = {"enabled": True, "warn": 3, "block": 6, "text": 10}
LLM_PARAMS_ENTRY = {"name": "gpu", "kind": "llamacpp", "params": {"*": {"temperature": 0.5, "max_tokens": 1000}},
                    "forced": {}, "override": {}, "presets": {},
                    "sent": {"chat": ["temperature", "top_k", "max_tokens"], "responses": ["temperature", "max_tokens"],
                             "messages": ["temperature", "max_tokens"]}, "loop": LOOP}


def llm_chat(count, result="same", name="bash", human=True):
    messages = [{"role": "user", "content": "go"}] if human else []
    for i in range(count):
        messages += [{"role": "assistant", "tool_calls": [{"id": f"c{i}", "function": {
            "name": name, "arguments": '{"command": "ls"}'}}]}, {"role": "tool", "tool_call_id": f"c{i}",
                                                                   "content": result}]
    return {"model": "m", "messages": messages, "tools": [{"type": "function"}]}


def test_llm_api(scenario):
    if scenario == "happy":
        assert rt.llm_api("/v1/chat/completions") == "chat" and rt.llm_api("/v1/messages") == "messages"
    elif scenario == "sad":
        assert rt.llm_api("/v1/models") is None and rt.llm_api("") is None and rt.llm_api(None) is None
    else:
        assert rt.llm_api("/gw/v1/responses/?x=1") == "responses"


def test_llm_family(scenario):
    if scenario == "happy":
        assert rt.llm_family(r"qwen-?3").search("Qwen3-Coder")
    elif scenario == "sad":
        assert rt.llm_family("(") is None and rt.llm_family(None) is None
    else:  # compiled once
        assert rt.llm_family("gpt-oss") is rt.llm_family("gpt-oss")


def test_llm_preset(scenario):
    families = [["qwen-?3", {"top_k": 20}]]
    if scenario == "happy":  # a model the start listed: its own preset first
        assert rt.llm_preset({"presets": {"m": {"top_k": 5}}, "families": families}, "m") == {"top_k": 5}
    elif scenario == "sad":
        assert rt.llm_preset({}, "m") == {} and rt.llm_preset({"families": [[1, {}], ["(", {}]]}, "m") == {}
    else:  # a model of the server not listed at the start: its family's preset
        assert rt.llm_preset({"presets": {}, "families": families}, "qwen3-8b") == {"top_k": 20}


def test_llm_model_refusal(scenario):
    entry = {"name": "s", "models": ["a", "b"]}
    if scenario == "happy":
        assert rt.llm_model_refusal(entry, {"model": "a"}) is None
        assert rt.llm_model_refusal({"name": "s", "models": None}, {"model": "z"}) is None  # any model of it
    elif scenario == "sad":
        assert "not among the models" in rt.llm_model_refusal(entry, {"model": "z"})
    else:  # a request without a model goes as it came; one given as anything but a name, or Ollama's "name": refused
        assert rt.llm_model_refusal(entry, {"messages": []}) is None
        assert "given as int" in rt.llm_model_refusal(entry, {"model": 5})
        assert "not among" in rt.llm_model_refusal(entry, {"name": "z"}) and \
            rt.llm_model_refusal(entry, {"name": "b"}) is None


def test_llm_instance_model(scenario):
    allowed = ["a", "org/b"]
    if scenario == "happy":  # LM Studio's first instance is the model's key, a further one KEY:N
        assert rt.llm_instance_model("a", allowed) == "a" and rt.llm_instance_model("org/b:2", allowed) == "org/b"
    elif scenario == "sad":  # another model's, an identifier of its own, no string: none (refused)
        assert rt.llm_instance_model("c", allowed) is None and rt.llm_instance_model("mine", allowed) is None
        assert rt.llm_instance_model(3, allowed) is None and rt.llm_instance_model("a", None) is None
    else:
        assert rt.llm_instance_model("a:1", allowed) is None and rt.llm_instance_model("a:\u0662", allowed) is None
        assert rt.llm_instance_model("a:9999", allowed) == "a" and rt.llm_instance_model("a:10000", allowed) is None


def test_llm_offered_text(scenario):
    if scenario == "happy":
        assert rt.llm_offered_text(["a", "b"]) == "a, b"
    elif scenario == "sad":
        assert rt.llm_offered_text([]) == ""
    else:  # ten named, the rest counted
        assert rt.llm_offered_text([str(n) for n in range(12)]).endswith("9 and 2 more")


def test_llm_unread_refusal(scenario):
    if scenario == "happy":  # with a list of models: an unread body is refused
        assert "cannot read (gzip" in rt.llm_unread_refusal({"name": "s", "models": ["a"]}, "gzip, application/json")
    elif scenario == "sad":  # any model of the server: nothing to refuse
        assert rt.llm_unread_refusal({"name": "s", "models": None}, "gzip") is None
    else:
        assert rt.llm_unread_refusal({"name": "s"}, "x") is None


def test_llm_limited_body(scenario):
    head = b"POST /api/generate HTTP/1.1\r\n\r\n"
    entry = {"name": "s", "models": ["a"]}
    plain = [("Content-Type", "application/json")]
    if scenario == "happy":
        body = b'{"model":"a","prompt":"x"}'
        new, parts, done = rt.llm_limited_body(head, [(body, body)], plain, entry)
        assert new == head and b"".join(raw for raw, _ in parts) == body and done == {}
    elif scenario == "sad":  # another model, an unread body
        body = b'{"model":"z"}'
        assert "not among" in rt.llm_limited_body(head, [(body, body)], plain, entry)[2]["refused"]
        assert "cannot read" in rt.llm_limited_body(head, [(b"\x1f\x8b", b"\x1f\x8b")],
                                                    [("Content-Encoding", "gzip")], entry)[2]["refused"]
    else:  # without a list nothing is read; an empty body passes
        parts = iter([(b"{", b"{")])
        assert rt.llm_limited_body(head, parts, plain, {"name": "s", "models": None})[1] is parts
        assert rt.llm_limited_body(head, [], plain, entry)[2] == {}


def test_llm_values(scenario):
    if scenario == "happy":
        values, forced = rt.llm_values({**LLM_PARAMS_ENTRY, "forced": {"*": ["temperature"]}}, "m")
        assert values == {"temperature": 0.5, "max_tokens": 1000} and forced == {"temperature"}
    elif scenario == "sad":
        assert rt.llm_values({}, "m") == ({}, set())
    else:  # the family's preset lowest, the start's override highest and forced
        entry = {**LLM_PARAMS_ENTRY, "presets": {"m": {"temperature": 0.6, "top_k": 20}}, "override": {"top_k": 5}}
        assert rt.llm_values(entry, "m") == ({"temperature": 0.5, "top_k": 5, "max_tokens": 1000}, {"top_k"})


def test_llm_apply_params(scenario):
    if scenario == "happy":
        document = {"model": "m"}
        assert rt.llm_apply_params(document, LLM_PARAMS_ENTRY, "chat") == {"temperature": 0.5, "max_tokens": 1000}
    elif scenario == "sad":  # an API the kind takes nothing on, and the agent's own values: unchanged
        document = {"model": "m", "temperature": 0.1, "max_tokens": 10}
        assert rt.llm_apply_params(document, LLM_PARAMS_ENTRY, "chat") == {} and document["max_tokens"] == 10
        assert rt.llm_apply_params({"model": "m"}, LLM_PARAMS_ENTRY, "completions") == {}
