    said, reported = [], []
    report = lambda *args, **kwargs: reported.append((args, kwargs))  # noqa: E731
    if scenario == "happy":  # a zero-width space in AGENTS.md: said and recorded, nothing changed
        (ws / "AGENTS.md").write_text("Use tabs.\u200b\n")
