def test_package_request(scenario):
    if scenario == "happy":
        assert rt.package_request("npm", "/left-pad/-/left-pad-1.3.0.tgz") == {
            "ecosystem": "npm", "kind": "download", "name": "left-pad", "version": "1.3.0", "form": "tarball"}
